INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 7, 'theory', 'Quiz: multiplexers and buses');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 0, 'A 2→1 multiplexer has selector S = 1. What goes to the output?', '["Input A", "Input B", "The negation of A", "Always zero"]', 1, 'The formula is Y = not S · A + S · B. At S = 1 the first term is zero, and the second one is B.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 1, 'How many 2→1 multiplexers are needed to build a 4→1 multiplexer?', '["2", "3", "4", "8"]', 1, 'Two at the first level (one per pair of inputs) and one at the second. An 8→1 multiplexer needs seven: 4 + 2 + 1.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 2, 'Which code on the inputs of a 2→4 decoder lights line Y2?', '["00", "01", "10", "11"]', 2, 'The code is read as a number: 10 is two. Exactly one line lights, the one whose number equals the code.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 3, 'What does a priority encoder do if I3 and I1 are lit at the same time?', '["Outputs code 00", "Outputs the code of the lower line (01)", "Outputs the code of the higher line (11)", "Reports an error and stops"]', 2, 'The higher number has priority: I3 wins, the output is 11. The extra output V shows that an input was active.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 7, 4, 'How do you implement the XOR of two variables on a 4→1 multiplexer?', '["Feed A and B to the data inputs", "Feed A and B to the selector, and the constants 0, 1, 1, 0 to the data inputs", "Feed constants to the selector", "You cannot: XOR is not a logic function"]', 1, 'A multiplexer picks the input whose number is set by the selector. If the truth table is written on the inputs and the variables are on the selector, you get any function of those variables.');
